CREATE TABLE IF NOT EXISTS continental_asset_passports (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), asset_id uuid NOT NULL REFERENCES continental_assets(id) ON DELETE CASCADE, passport_number text NOT NULL UNIQUE, passport_version integer NOT NULL DEFAULT 1, passport_status text NOT NULL DEFAULT 'Draft', jurisdiction_code text, asset_identity jsonb NOT NULL DEFAULT '{}'::jsonb, geography jsonb NOT NULL DEFAULT '{}'::jsonb, parties jsonb NOT NULL DEFAULT '{}'::jsonb, ownership jsonb NOT NULL DEFAULT '{}'::jsonb, title_and_tenure jsonb NOT NULL DEFAULT '{}'::jsonb, community_and_indigenous_rights jsonb NOT NULL DEFAULT '{}'::jsonb, regulatory_position jsonb NOT NULL DEFAULT '{}'::jsonb, environmental_position jsonb NOT NULL DEFAULT '{}'::jsonb, mineral_rights jsonb NOT NULL DEFAULT '{}'::jsonb, carbon_rights jsonb NOT NULL DEFAULT '{}'::jsonb, encumbrances jsonb NOT NULL DEFAULT '{}'::jsonb, valuation jsonb NOT NULL DEFAULT '{}'::jsonb, diligence jsonb NOT NULL DEFAULT '{}'::jsonb, evidence_summary jsonb NOT NULL DEFAULT '{}'::jsonb, risk_summary jsonb NOT NULL DEFAULT '{}'::jsonb, investment_position jsonb NOT NULL DEFAULT '{}'::jsonb, clearance_summary jsonb NOT NULL DEFAULT '{}'::jsonb, issued_at timestamptz, issued_by_reference text, effective_from timestamptz, effective_to timestamptz, supersedes_passport_id uuid REFERENCES continental_asset_passports(id) ON DELETE SET NULL, canonical_hash text, verification_uri text, status text NOT NULL DEFAULT 'Active', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(asset_id,passport_version));
CREATE TABLE IF NOT EXISTS asset_passport_events (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), passport_id uuid NOT NULL REFERENCES continental_asset_passports(id) ON DELETE CASCADE, event_type text NOT NULL, event_summary text NOT NULL, source_reference text, evidence_reference text, actor_reference text, occurred_at timestamptz NOT NULL DEFAULT now(), previous_hash text, event_hash text, status text NOT NULL DEFAULT 'Recorded');
CREATE TABLE IF NOT EXISTS asset_passport_clearances (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), passport_id uuid NOT NULL REFERENCES continental_asset_passports(id) ON DELETE CASCADE, clearance_domain text NOT NULL, clearance_status text NOT NULL DEFAULT 'Pending', blocking boolean NOT NULL DEFAULT false, authority_reference text, evidence_reference text, reviewer_reference text, rationale text, decided_at timestamptz, expiry_date date, status text NOT NULL DEFAULT 'Open', UNIQUE(passport_id,clearance_domain));
CREATE INDEX IF NOT EXISTS idx_passport_asset ON continental_asset_passports(asset_id,passport_version DESC);
CREATE INDEX IF NOT EXISTS idx_passport_events ON asset_passport_events(passport_id,occurred_at DESC);
CREATE INDEX IF NOT EXISTS idx_passport_clearances ON asset_passport_clearances(passport_id,blocking,clearance_status);